254	  /* Start DSI */

255	  HAL_DSI_Start(&hdsi_eval);
256	  /* Enable the DSI BTW for read operations */
257	  HAL_DSI_ConfigFlowControl(&hdsi_eval, DSI_FLOW_CONTROL_BTA);
