379	  hltdc_eval.Init.Backcolor.Blue = 0;

380	  hltdc_eval.Init.Backcolor.Green = 0;
381	  hltdc_eval.Init.Backcolor.Red = 0;
382	  hltdc_eval.Init.PCPolarity = LTDC_PCPOLARITY_IPC;
