387	  
388	  /* Initialize the LTDC */  
389	  HAL_LTDC_Init(&hltdc_eval);
390	
391	  /* Enable the DSI host and wrapper after the LTDC initialization
392	     To avoid any synchronization issue, the DSI shall be started after enabling the LTDC */
393	  HAL_DSI_Start(&(hdsi_eval));
394	  
395	#if !defined(DATA_IN_ExtSDRAM)
396	  /* Initialize the SDRAM */
397	  BSP_SDRAM_Init();
398	#endif /* DATA_IN_ExtSDRAM */
399	  
400	  /* Initialize the font */
401	  BSP_LCD_SetFont(&LCD_DEFAULT_FONT);
402	  /************************End LTDC Initialization*******************************/
403	
404	  /* Checking the ID to determine the type of component */
405	  if (Lcd_Driver_Type == LCD_CTRL_NT35510)
406	  {
407	    /***********************NT35510 Initialization********************************/  
408	    /* Initialize the NT35510 LCD Display IC Driver (TechShine LCD IC Driver)
409	    * depending on configuration set in 'hdsivideo_handle'.
410	    */
411	    NT35510_Init(NT35510_FORMAT_RGB888, orientation);
412	    /***********************End NT35510 Initialization****************************/
413	  }
414	  else if (Lcd_Driver_Type == LCD_CTRL_OTM8009A)
415	  {
416	    /***********************OTM8009A Initialization********************************/  
417	    /* Initialize the OTM8009A LCD Display IC Driver (KoD LCD IC Driver)
418	    *  depending on configuration set in 'hdsivideo_handle'.
419	    */
420	    OTM8009A_Init(OTM8009A_FORMAT_RGB888, orientation);
421	    /***********************End OTM8009A Initialization****************************/ 
422	  }
423	  else
424	  {
425	    return LCD_ERROR;
426	  }
427	
428	  return LCD_OK;
429	}
