390	  gpio_init_structure.Pin = DISCO_I2C1_SCL_PIN;
391	  gpio_init_structure.Mode = GPIO_MODE_OUTPUT_OD;
392	  gpio_init_structure.Pull = GPIO_NOPULL;
393	  gpio_init_structure.Speed = GPIO_SPEED_FAST;
394	  gpio_init_structure.Alternate = 0;
395	  HAL_GPIO_Init( DISCO_I2C1_SCL_SDA_GPIO_PORT, &gpio_init_structure );
396	  for(uint8_t count = 10; count > 0; count-- )
397	  {
398	    HAL_GPIO_WritePin( DISCO_I2C1_SCL_SDA_GPIO_PORT, DISCO_I2C1_SCL_PIN, GPIO_PIN_SET );
399	    HAL_Delay(1);
400	    HAL_GPIO_WritePin( DISCO_I2C1_SCL_SDA_GPIO_PORT, DISCO_I2C1_SCL_PIN, GPIO_PIN_RESET );
401	    HAL_Delay(1);
402	  }
403	#endif /* USE_STM32469I_DISCO_REVC */
